input.old_string:
input { width: 100%; padding: 10px 12px; margin-bottom: 4px; border: 1px solid #c8c2b8; border-radius: 6px; font-size: 15px }
.field { margin-bottom: 16px }
.error { font-size: 13px; color: #e2685f; min-height: 16px }
.summary { color: #e2685f; font-size: 14px; margin-bottom: 18px }

input.new_string:
input { width: 100%; padding: 10px 12px; margin-bottom: 4px; border: 1px solid #8a8274; border-radius: 6px; font-size: 15px }
input[aria-invalid="true"] { border-color: #c0392b }
.field { margin-bottom: 16px }
.error { font-size: 13px; color: #c0392b; min-height: 16px }
.summary { color: #c0392b; font-size: 14px; margin-bottom: 18px }

